#!/bin/bash
# data fork (round G): arm `uog1` = uof2's recipe (PP-OCRv5 block in every prompt) on manifest ug1_nc (323,264 rows; 5,051 steps).
# Node-side chain, re-runnable, generated by vg_genarm.py from round F's chain (md5 35edce68): restage from S3 (18 base-model shards checked against
# the Hub's sha256; every OCR file checksum-checked on every start; one-time OCR pass for the images round F's cache lacks) -> smoke once -> train with S3
# checkpoints every 100 steps (resumes) -> dev gates 1000 / 2000 / 3000 / 4000 / 5051 (stop only on collapse, dev < 85) -> final dev >= 89.93 or no public read ->
# RBH two numbers (reported) -> proxy HELD with the uof2 reference (uof2/ckpt_04519) in the same processes -> ONE public no-WG read. No soup sweep.
# No Winoground on this node (WG=0: the launcher never touches eval_restricted). Prereg: AGENT_NOTES 2026-11-15 (PREREG Arms ug1 + uog1).
# usage: uog1_chain.sh <node tag: p12 | p4de> <run name: uog1>
set -u
export AWS_DEFAULT_REGION=us-east-2
TAG=$1; NAME=$2
Q=/data/local/qv; UW=/data/local/uog1; L=$UW/logs/uog1_chain_$NAME.log
B=s3://YOUR_BUCKET/jev-race; V=$B/engineering/vision; A=$V/recipe_a; U=$V/recipe_g/uog1; C=$B/fleetq/claims
MANIFEST=ug1_nc; MSHA=65e7224c571fa5c814630229ca234e68c96ba4f78fd52796f3bae90dcfaad20b; STEPS=5051; GSTEPS=1000,2000,3000,4000,5051
mkdir -p $UW/logs $UW/code $Q/logs $Q/code $Q/kit $Q/dev $Q/public $Q/data/img
log(){ echo "[uog1 $(date -u +%H:%M:%SZ)] $*" >> $L; }
exec 9> $UW/chain.lock; flock -n 9 || { log "another uog1 chain holds the lock on this node: exit"; exit 0; }
log "START $TAG $NAME manifest=$MANIFEST steps=$STEPS seed=20261114 r16/a32 host=$(hostname)"
mirror(){ aws s3 cp --quiet $L $U/logs/uog1_chain_$NAME.$TAG.log; }
aws s3 cp --quiet --recursive $U/code/ $UW/code/ --exclude uog1_chain.sh && (cd $UW/code && md5sum -c MD5SUMS > $UW/logs/chain_code_md5.log 2>&1) && log "CODE launcher $(md5sum < $UW/code/qv_arm_uog.sh | cut -c1-8) chain $(md5sum < $UW/code/uog1_chain.sh | cut -c1-8)" || { log CODE_FETCH_FAIL; mirror; exit 3; }
AR=$UW/code/qv_arm_uog.sh
aws s3 ls $U/state/${NAME}_chain_done > /dev/null 2>&1 && { log "CHAIN_DONE already on S3"; exit 0; }
aws s3 ls $U/state/${NAME}_fail > /dev/null 2>&1 && { log "FAIL marker on S3: not relaunching; remove $U/state/${NAME}_fail to retry"; exit 5; }
[ "$(nvidia-smi -L 2>/dev/null | wc -l)" = "8" ] || { log "NOT_8_GPUS"; mirror; exit 6; }
echo started | aws s3 cp --quiet - $U/state/${NAME}_started
NL=$(aws s3 cp --quiet $U/state/${NAME}_launches - 2>/dev/null | tr -dc 0-9 | cut -c1-3); NL=$(( ${NL:-0} + 1 )); echo $NL | aws s3 cp --quiet - $U/state/${NAME}_launches; log "chain launch number $NL"
[ $NL -le 15 ] || { log "TOO_MANY_LAUNCHES ($NL): something restarts in a loop; holding"; echo "more than 15 chain launches $(date -u +%FT%TZ) on $TAG" | aws s3 cp --quiet - $U/state/${NAME}_fail; mirror; exit 5; }
aws s3 ls $C/ | grep -q "${TAG}__dataG-${NAME}__" || echo "data fork (round G): arm $NAME = uof2's recipe on ug1_nc (323,264 rows, 5,051 steps), all 8 GPUs ~12 h, node-side chain uog1_chain.sh, guard on worker-node ops/recipe_g/uog1/uog1_guard.sh; written $(date -u +%Y-%m-%dT%H:%M:%SZ)" | aws s3 cp --quiet - $C/${TAG}__dataG-${NAME}__$(( $(date -u +%s) + 64800 ))
cc1d_fix(){ # qv_env.sh installs the optional causal-conv1d whenever pip can (11-15 on p12: a cached wheel built for CUDA 12 -> "libcudart.so.12" import error ->
  # the model class no longer imports). The earlier arms on these nodes ran on the torch fallback ("CC1D_SKIPPED"): put the venv back in that state, re-run the stamp.
  local EL=$Q/logs/env.log
  tail -n 3 $EL | grep -q ENV_FUNCTIONAL_FAIL || return 0
  $Q/venv/bin/python -c "import causal_conv1d" > /dev/null 2>&1 && return 0
  $Q/venv/bin/pip show causal-conv1d > /dev/null 2>&1 || return 0
  $Q/venv/bin/pip uninstall -y -q causal-conv1d >> $EL 2>&1
  $Q/venv/bin/python - >> $EL 2>&1 <<'PY' || { echo "[env $(date -u +%H:%M:%SZ)] CC1D_BROKEN_REMOVED but the stamp still fails" >> $EL; return 1; }
import torch, transformers, peft, fla
from transformers import Qwen3_5ForConditionalGeneration, AttentionInterface
x = torch.randn(256, 256, device="cuda", dtype=torch.bfloat16); y = (x @ x).float().sum().item()
print("FUNCTIONAL", torch.__version__, transformers.__version__, peft.__version__, fla.__version__, torch.cuda.get_device_name(0), torch.cuda.device_count())
PY
  touch $Q/venv.functional.ok
  sed -i "$((E0 + 1)),\$ s/ENV_FUNCTIONAL_FAIL/ENV_STAMP_FAILED_WITH_BROKEN_CC1D_WHEEL/" $EL
  echo "[env $(date -u +%H:%M:%SZ)] CC1D_BROKEN_REMOVED (torch fallback, as the earlier arms) ENV_FUNCTIONAL_OK" >> $EL
}
if [ ! -f $Q/UOG1_RESTAGE_OK ]; then
  aws s3 sync --quiet $A/code/qv/ $Q/code/ && (cd $Q/code && md5sum -c MD5SUMS > $Q/logs/code_md5.log 2>&1) && log CODE_OK || { log CODE_MD5_BAD; mirror; exit 3; }
  L0=$(wc -l < $L); E0=$(wc -l < $Q/logs/env.log 2>/dev/null || echo 0)  # this start's log lines only: an earlier failed restage on the same disk is not held against this one
  ( bash $Q/code/qv_env.sh; cc1d_fix; log "ENV $(tail -2 $Q/logs/env.log | tr '\n' ' ')" ) &
  ( [ -d $Q/kit/kit_vis ] || { aws s3 cp --quiet $A/code/kit_vis.tgz $Q/kit/ && tar xzf $Q/kit/kit_vis.tgz -C $Q/kit; }
    D=$V/recipe_dev; [ -f $Q/dev/dev_rows.jsonl ] || { aws s3 cp --quiet $D/dev_rows.jsonl $Q/dev/ && aws s3 cp --quiet $D/dev_rows.header.json $Q/dev/ && aws s3 cp --quiet $D/img_dev.tar $Q/dev/ && tar xf $Q/dev/img_dev.tar -C $Q/dev && rm -f $Q/dev/img_dev.tar; }
    [ "$(sha256sum $Q/dev/dev_rows.jsonl | cut -d' ' -f1)" = "082d1eceec1f34ce122871f133f07e1200807c3ad19d5a8fe9acd3f30a75a72d" ] && log DEV_OK || log DEV_SHA_BAD
    if [ ! -f $Q/public/suite/vision-rows-noWG.jsonl ]; then  # the no-Winoground suite only; nothing from eval_restricted is ever fetched here
      aws s3 cp --quiet $V/suite/suite_noWG.tar $Q/public/ && aws s3 cp --quiet $V/suite/suite_noWG.tar.md5 $Q/public/
      [ "$(awk '{print $1}' $Q/public/suite_noWG.tar.md5)" = "$(md5sum < $Q/public/suite_noWG.tar | cut -d' ' -f1)" ] && tar xf $Q/public/suite_noWG.tar -C $Q/public && rm -f $Q/public/suite_noWG.tar || log SUITE_MD5_BAD
      [ -f $Q/public/suite/vision-rows-noWG.jsonl ] || aws s3 cp --quiet $V/work/vision-rows-noWG.jsonl $Q/public/suite/vision-rows-noWG.jsonl
    fi
    [ "$(sha256sum $Q/public/suite/vision-rows-noWG.jsonl | cut -d' ' -f1)" = "0d44a006e575363aee592dd7a03a5ae45cf095c45eef6ce74079e8a040ef5d3c" ] && log PUBLIC_SUITE_OK || log PUBLIC_ROWS_SHA_BAD ) &
  wait
  # base model: every shard the index names must be there, complete, and hold the tensors the index assigns to it (and match the Hub's sha256)
  MC=1; for try in 1 2 3; do
    $Q/venv/bin/python $UW/code/uog1_modelcheck.py $Q/models/qwen38_27b 1d4bf0f2ff6012fd82039f2fa52739d0dd7c60c0 > $UW/logs/modelcheck_$try.log 2>&1; MC=$?
    log "MODELCHECK try $try rc=$MC $(tail -1 $UW/logs/modelcheck_$try.log | cut -c1-300)"
    [ $MC -eq 0 ] && break
    HF_HUB_DISABLE_XET=1 $Q/venv/bin/python -c "
from huggingface_hub import snapshot_download
snapshot_download('Qwen/Qwen3.8-27B', revision='1d4bf0f2ff6012fd82039f2fa52739d0dd7c60c0', local_dir='/data/local/qv/models/qwen38_27b', token=False, max_workers=16)" >> $Q/logs/env.log 2>&1
  done
  bad=$( (tail -n +$((L0 + 1)) $L; tail -n +$((E0 + 1)) $Q/logs/env.log) | grep -c -E "_BAD|ENV_FUNCTIONAL_FAIL|MODEL_FAIL")
  if [ -f $Q/venv.functional.ok ] && [ $MC -eq 0 ] && [ "$bad" = "0" ]; then touch $Q/UOG1_RESTAGE_OK; log RESTAGE_OK; else
    log "RESTAGE_FAIL bad=$bad modelcheck_rc=$MC"; n=$(aws s3 cp --quiet $U/state/${NAME}_restage_fails - 2>/dev/null || echo 0); echo $(( ${n:-0} + 1 )) | aws s3 cp --quiet - $U/state/${NAME}_restage_fails; mirror; exit 4; fi
fi
# --- OCR (uog1). Every OCR file is fetched and checksum-checked on EVERY chain start (a replaced spot worker has an empty disk).
FO=$V/recipe_f/ocr; GO=$V/recipe_g/ocr; OCRF=ocr/ocr_train_ug1.jsonl
ocr_get(){ # <s3 url> <local path> <md5>: keep a local file only if its md5 is right, else fetch and check
  [ -n "$3" ] || return 1
  [ -f $2 ] && [ "$(md5sum < $2 | cut -d' ' -f1)" = "$3" ] && return 0
  aws s3 cp --quiet $1 $2.dl && [ "$(md5sum < $2.dl | cut -d' ' -f1)" = "$3" ] && mv $2.dl $2 || { log "OCR_STAGE_BAD $(basename $2)"; return 1; }
}
ocr_stage(){
  mkdir -p $Q/ocr $Q/rbh_gate $Q/priv
  ocr_get $A/ocr/ocr_dev.jsonl $Q/ocr/ocr_dev.jsonl 5b62c8a22424c56bae8f3cfb0375cbe9 && ocr_get $A/ocr/ocr_public_EVAL_ONLY.jsonl $Q/ocr/ocr_public.jsonl 212232c925a9f94c9b4c6b0506d73db9 \
    && ocr_get $FO/ocr_train_uf1.jsonl $Q/ocr/ocr_train_uf1.jsonl 1232cbfffd9809ed9abaaa9376c93b7f && ocr_get $V/recipe_privlike/ocr/ocr_rbh.jsonl $Q/rbh_gate/ocr_rbh.jsonl ff5023125c676eed1f30524afa4c0e32 \
    && ocr_get $V/recipe_privlike/ocr/ocr_priv.jsonl $Q/priv/ocr_priv.jsonl 98776a8972ec6d019423092a9e73946b
}
ocr_stage && log "OCR_STAGE_OK dev / public / round F train cache / rbh / priv present, md5 ok" || { log "OCR_STAGE_FAIL: not starting the arm"; mirror; exit 4; }
stage_images(){ env MAN=$MANIFEST SHA=$MSHA STAGE_ONLY=1 bash $AR _${NAME}_stage 0 0 && tail -n 1 $Q/logs/arm__${NAME}_stage.log | grep -q "STAGE_ONLY: inputs staged"; }
if aws s3 ls $GO/MD5SUMS_ocr_ug1 > /dev/null 2>&1; then
  aws s3 cp --quiet $GO/MD5SUMS_ocr_ug1 $Q/ocr/MD5SUMS_ocr_ug1 && ocr_get $GO/ocr_train_ug1.jsonl $Q/$OCRF "$(grep ' ocr_train_ug1.jsonl$' $Q/ocr/MD5SUMS_ocr_ug1 | cut -d' ' -f1)" \
    && log "OCR_CACHE_FROM_S3 $(wc -l < $Q/$OCRF) images" || { log OCR_CACHE_S3_BAD; mirror; exit 4; }
else
  # one-time OCR pass: PP-OCRv5 mobile det + en mobile rec, Arm UO's ocr_pass.py unchanged, Arm UO's PINNED model files; images the round F cache lacks
  stage_images || { log "IMAGE_STAGE_FAIL $(tail -2 $Q/logs/arm__${NAME}_stage.log | tr '\n' ' ' | cut -c1-300)"; mirror; exit 5; }
  log "IMAGES_STAGED for the OCR pass"
  aws s3 cp --quiet $A/code/qv_extra/ocr_pass.py $UW/code/ocr_pass.py && aws s3 cp --quiet $A/code/qv_extra/ocr_merge.py $UW/code/ocr_merge.py || { log OCR_CODE_FAIL; mirror; exit 3; }
  OL=$Q/logs/ocr_ug1.log; OD=$Q/ocr/ug1; mkdir -p $OD/lists $OD/logs
  if [ ! -f $Q/ocrvenv.ok ]; then
    python3 -m venv $Q/ocrvenv && $Q/ocrvenv/bin/pip install -q --upgrade pip >> $OL 2>&1
    $Q/ocrvenv/bin/pip install -q paddlepaddle-gpu==3.2.0 -i https://www.paddlepaddle.org.cn/packages/stable/cu126/ >> $OL 2>&1 || { log PADDLE_GPU_INSTALL_FAIL; mirror; exit 2; }
    sudo -n env DEBIAN_FRONTEND=noninteractive apt-get update -q >> $OL 2>&1; sudo -n env DEBIAN_FRONTEND=noninteractive apt-get install -y -q libgl1 libglib2.0-0 >> $OL 2>&1
    $Q/ocrvenv/bin/pip install -q "paddleocr>=3.1" "paddlex[ocr]==3.7.2" >> $OL 2>&1 && touch $Q/ocrvenv.ok || { log OCR_PIP_FAIL; mirror; exit 2; }
  fi
  [ -e /usr/lib/x86_64-linux-gnu/libGL.so.1 ] || { sudo -n env DEBIAN_FRONTEND=noninteractive apt-get update -q >> $OL 2>&1; sudo -n env DEBIAN_FRONTEND=noninteractive apt-get install -y -q libgl1 libglib2.0-0 >> $OL 2>&1; }
  $Q/ocrvenv/bin/pip freeze 2>/dev/null | grep -iE "^(paddle|opencv|numpy|shapely|pyclipper)" > $Q/ocr/pip_freeze_ug1.txt
  MD=$HOME/.paddlex/official_models; mkdir -p $MD
  aws s3 cp --quiet $A/ocr/ocr_models.tar $Q/ocr/ocr_models.tar && aws s3 cp --quiet $A/ocr/ocr_models.md5 $Q/ocr/ocr_models.md5 && tar xf $Q/ocr/ocr_models.tar -C $MD && (cd $MD && md5sum -c --quiet $Q/ocr/ocr_models.md5) || { log OCR_MODELS_PIN_FAIL; mirror; exit 4; }
  log "OCR_ENV $(grep -iE '^paddle' $Q/ocr/pip_freeze_ug1.txt | tr '\n' ' ') models pinned $(wc -l < $Q/ocr/ocr_models.md5) files; gpu $(nvidia-smi --query-gpu=name --format=csv,noheader | head -1)"
  python3 - <<'PY' >> $L 2>&1 || { log OCR_LISTS_FAIL; mirror; exit 6; }
import json, random
Q = "/data/local/qv"
need = set()
for l in open(f"{Q}/data/ug1_nc.jsonl"):
    need.update(json.loads(l)["images"])
have = {json.loads(l)["image"] for l in open(f"{Q}/ocr/ocr_train_uf1.jsonl")}
new, old = sorted(need - have), sorted(need & have)
open(f"{Q}/ocr/ug1/lists/all.txt", "w").write("\n".join(sorted(need)) + "\n")
open(f"{Q}/ocr/ug1/lists/new.txt", "w").write("\n".join(new) + "\n")
random.seed(20261115)
open(f"{Q}/ocr/ug1/lists/ident.txt", "w").write("\n".join(sorted(random.sample(old, 400))) + "\n")
print(f"[uog1 ocr] images in ug1_nc {len(need)}; already in the round F cache {len(old)}; new {len(new)}")
PY
  # identity gate: 400 images that already have OCR text, read again on this node, must give the same text on >= 97%
  for k in 0 1 2 3 4 5 6 7; do CUDA_VISIBLE_DEVICES=$k $Q/ocrvenv/bin/python $UW/code/ocr_pass.py $OD/lists/ident.txt $Q/data/img $OD/ident_$k.jsonl $k 8 gpu:0 > $OD/logs/ident_$k.log 2>&1 & done; wait
  SAME=$(python3 - <<'PY'
import glob, json
Q = "/data/local/qv/ocr"
def norm(r):
    ls = [x for x in r["lines"] if x["score"] >= 0.5]
    ls.sort(key=lambda x: (round(x["box"][1] / 12), x["box"][0]))
    return [x["text"] for x in ls]
want = {l.strip() for l in open(f"{Q}/ug1/lists/ident.txt") if l.strip()}
old = {}
for l in open(f"{Q}/ocr_train_uf1.jsonl"):
    r = json.loads(l)
    if r["image"] in want:
        old[r["image"]] = norm(r)
new = {}
for f in glob.glob(f"{Q}/ug1/ident_*.jsonl"):
    for l in open(f):
        r = json.loads(l); new[r["image"]] = norm(r)
same = sum(new[k] == old[k] for k in new)
print(f"{same}/{len(new)} {same / max(1, len(want)):.4f}")
PY
)
  log "OCR_IDENTITY same_text $SAME (denominator: the 400 listed images)"
  python3 -c "import sys; sys.exit(0 if float('$(echo $SAME | awk '{print $2}')') >= 0.97 else 1)" || { log "OCR_IDENTITY_BELOW_0.97: stop for inspection"; echo "ocr identity gate $SAME $(date -u +%FT%TZ) on $TAG" | aws s3 cp --quiet - $U/state/${NAME}_fail; aws s3 cp --quiet --recursive $OD/logs $GO/ident_fail_logs_$TAG/ 2>/dev/null; mirror; exit 5; }
  NNEW=$(grep -c . $OD/lists/new.txt)
  PIDS=""; for k in $(seq 0 23); do CUDA_VISIBLE_DEVICES=$((k % 8)) $Q/ocrvenv/bin/python $UW/code/ocr_pass.py $OD/lists/new.txt $Q/data/img $OD/shard_$k.jsonl $k 24 gpu:0 > $OD/logs/new_$k.log 2>&1 & PIDS="$PIDS $!"; done
  bad=0; for j in $PIDS; do wait $j || bad=$((bad + 1)); done
  [ $bad = 0 ] || { log "OCR_SHARD_FAIL $bad: $(tail -2 $OD/logs/new_0.log | tr '\n' ' ' | cut -c1-300)"; mirror; exit 6; }
  python3 $UW/code/ocr_merge.py $OD/lists/new.txt $OD $Q/ocr/ocr_train_ug1_new.jsonl > $OD/merge_new.json 2>&1 || { log "OCR_MERGE_FAIL $(cut -c1-300 $OD/merge_new.json)"; mirror; exit 6; }
  log "OCR_NEW_OK $NNEW images: $(cat $OD/merge_new.json)"
  python3 - <<'PY' > $Q/ocr/ug1/merge_all.json 2>&1 || { log "OCR_FINAL_MERGE_FAIL $(cut -c1-300 $Q/ocr/ug1/merge_all.json)"; mirror; exit 6; }
import json
Q = "/data/local/qv/ocr"
want = [l.rstrip("\n") for l in open(f"{Q}/ug1/lists/all.txt") if l.strip()]
got = {}
for f in ("ocr_train_uf1.jsonl", "ocr_train_ug1_new.jsonl"):  # the new pass covers only images the round F cache lacks; old lines verbatim
    for l in open(f"{Q}/{f}"):
        got[json.loads(l)["image"]] = l if l.endswith("\n") else l + "\n"
miss = [p for p in want if p not in got]
assert not miss, ("missing", len(miss), miss[:3])
with open(f"{Q}/ocr_train_ug1.jsonl.tmp", "w") as f:
    for p in want:
        f.write(got[p])
print(json.dumps({"images": len(want)}))
PY
  mv $Q/ocr/ocr_train_ug1.jsonl.tmp $Q/$OCRF
  (cd $Q/ocr && md5sum ocr_train_ug1.jsonl ocr_train_ug1_new.jsonl > MD5SUMS_ocr_ug1)
  ok=0; for f in ocr_train_ug1.jsonl ocr_train_ug1_new.jsonl pip_freeze_ug1.txt; do aws s3 cp --quiet $Q/ocr/$f $GO/$f && [ "$(md5sum < $Q/ocr/$f)" = "$(aws s3 cp --quiet $GO/$f - | md5sum)" ] && ok=$((ok+1)); done
  aws s3 sync --quiet $OD/lists $GO/lists/; aws s3 cp --quiet $OD/merge_new.json $GO/merge_new.json; aws s3 cp --quiet $OL $GO/ocr_ug1.log 2>/dev/null
  echo "$SAME identity re-read on $TAG ($(nvidia-smi --query-gpu=name --format=csv,noheader | head -1)), $(date -u +%FT%TZ)" | aws s3 cp --quiet - $GO/identity_ug1.txt
  [ $ok = 3 ] && aws s3 cp --quiet $Q/ocr/MD5SUMS_ocr_ug1 $GO/MD5SUMS_ocr_ug1 && [ "$(md5sum < $Q/ocr/MD5SUMS_ocr_ug1)" = "$(aws s3 cp --quiet $GO/MD5SUMS_ocr_ug1 - | md5sum)" ] \
    && log "OCR_CACHE_BUILT $(cat $OD/merge_all.json) S3_OK 4/4 $GO/" || { log "OCR_CACHE_S3_BAD $ok/3"; mirror; exit 7; }
fi
stage_images || { log "IMAGE_STAGE_FAIL $(tail -2 $Q/logs/arm__${NAME}_stage.log | tr '\n' ' ' | cut -c1-300)"; mirror; exit 5; }
python3 - <<'PY' >> $L 2>&1 || { log "OCR_COVERAGE_FAIL: not starting the arm"; mirror; exit 4; }
import json
Q = "/data/local/qv"
have = {json.loads(l)["image"] for l in open(f"{Q}/ocr/ocr_train_ug1.jsonl")}
need = set()
for l in open(f"{Q}/data/ug1_nc.jsonl"):
    need.update(json.loads(l)["images"])
print(f"[uog1 ocr] manifest images {len(need)}, missing from the OCR cache {len(need - have)}")
assert not (need - have)
PY
UA="MAN=$MANIFEST SHA=$MSHA OCR=$OCRF LORA_R=16 LORA_A=32 SEED=20261114 RBH_DIAG=1 HELD=1 REF=uof2/ckpt_04519 WG=0"; cd $Q
if ! aws s3 ls $U/state/${NAME}_${TAG}_smoke_ok > /dev/null 2>&1 && ! aws s3 ls $A/runs/$NAME/ckpt/ 2>/dev/null | grep -q ckpt_; then
  awk 'NR%46==1' $Q/dev/dev_rows.jsonl > $Q/logs/uog1_dev65.jsonl; N=_${NAME}_smoke_$(date -u +%H%M%S)
  ( exec 9>&-; while sleep 5; do nvidia-smi --query-gpu=memory.used --format=csv,noheader,nounits | sort -n | tail -1; done > $Q/logs/uog1_smoke_mem.txt ) & MP=$!
  env $UA NPROC=8 PORT=29633 SAVE=2 GATE_FILE=$Q/logs/uog1_dev65.jsonl PUBLIC=0 STEPS=4 GSTEPS=2,4 bash $AR $N 0 0
  PEAK=$(sort -n $Q/logs/uog1_smoke_mem.txt | tail -1); kill $MP
  sleep 20; mv $Q/runs/$N $Q/runs/${N}_local1
  env $UA NPROC=8 PORT=29633 SAVE=2 GATE_FILE=$Q/logs/uog1_dev65.jsonl PUBLIC=0 RBH_SMOKE=1 STEPS=6 GSTEPS=6 bash $AR $N 0 0
  b1=$(grep -c "TRAIN_RC=0" $Q/logs/arm_$N.log); b2=$(grep -c "PULLED_S3_CKPT ckpt_00004" $Q/logs/arm_$N.log); b3=$(grep -c '"event": "gate"' $Q/runs/$N/train_log.jsonl); b4=$(grep "RBH_GATE pass" $Q/logs/arm_$N.log | grep -c '"read": 1530')
  b5=$(python3 -c "import json; d=json.load(open('$Q/runs/$N/held.json')); print(int(d['arm']['read'] > 1000 and d.get('ref', {}).get('read', 0) > 1000))" 2>/dev/null)
  # the 6 smoke steps are the arm's own first 6 steps (same manifest, same seed): rows used / skipped per step and the ADE rows among them
  b6=$(python3 $UW/code/uog1_rows_check.py $Q/data/$MANIFEST.jsonl 20261114 $Q/runs/${N}_local1/train_log.jsonl $Q/runs/$N/train_log.jsonl 2> $UW/logs/rows_check_smoke.err | tail -1)
  b7=$(echo "$b6" | grep -c '"ok": true')
  b8=$(ls -d $Q/eval_restricted/wg_suite 2>/dev/null | wc -l)
  b9=$(python3 -c "import json; print(int(json.load(open('$Q/runs/$N/gate_00006.json')).get('ocr') is True))" 2>/dev/null)
  log "smoke $N: train_ok=$b1 s3_resume=$b2 dev_reads_in_log=$b3 rbh_full_read=$b4 held_ok=${b5:-0} rows_ok=$b7 winoground_dirs=$b8 dev_ocr_flag=${b9:-0} peak_train_mib=$PEAK $(grep -o '"lora_params": [0-9]*' $Q/runs/$N/train_log.jsonl | tail -1) $(grep '"event": "step"' $Q/runs/$N/train_log.jsonl | tail -1 | grep -o '"s": [0-9.]*') :: $(tail -1 $Q/logs/train_$N.out | cut -c1-200)"
  log "smoke rows: $(echo "$b6" | cut -c1-900)"
  if [ "$b1" = "2" ] && [ "$b2" = "1" ] && [ "$b3" -ge 1 ] && [ "$b4" -ge 1 ] && [ "${b5:-0}" = "1" ] && [ "$b7" = "1" ] && [ "$b8" = "0" ] && [ "${b9:-0}" = "1" ]; then log "SMOKE_OK $NAME"; echo ok | aws s3 cp --quiet - $U/state/${NAME}_${TAG}_smoke_ok; else log "SMOKE_FAIL $NAME: NOT launching"; echo "smoke failed $(date -u +%FT%TZ) on $TAG: train_ok=$b1 s3_resume=$b2 dev=$b3 rbh=$b4 held=${b5:-0} rows=$b7 wg=$b8" | aws s3 cp --quiet - $U/state/${NAME}_fail; mirror; exit 3; fi
  mirror
fi
log "$NAME launch"
( exec 9>&-; while sleep 600; do mirror; done ) & MIR=$!  # helper loops do not hold the chain lock
env $UA STEPS=$STEPS GSTEPS=$GSTEPS PUBLIC=1 bash $AR $NAME 85 89.93
log "$NAME arm rc=$? :: $(grep -E 'FINAL_DEV|RBH_GATE pass|HELD \{|SCORE RC' $Q/logs/arm_$NAME.log | cut -c1-700 | tr '\n' ' ')"
if grep -qE "\] DONE|PUBLIC_READ_EXISTS" $Q/logs/arm_$NAME.log; then
  python3 $UW/code/uog1_result.py $NAME $MANIFEST > $UW/logs/uog1_result.log 2>&1; log "result rc=$? $(tail -1 $UW/logs/uog1_result.log | cut -c1-900)"
  aws s3 sync --quiet $Q/runs/$NAME $A/runs/$NAME/ --exclude "ckpt_*" --exclude "public_read/rows/*"
  mirror; echo done | aws s3 cp --quiet - $U/state/${NAME}_chain_done; log CHAIN_DONE
elif grep -q "FINAL_DEV index=-1 " $Q/logs/arm_$NAME.log; then
  log "FINAL_DEV_READ_MISSING: the final checkpoint exists but its dev read was lost (node died during the read). No public read. Needs a hand: read dev on ckpt_$(printf %05d $STEPS), then decide"
  echo "final dev read missing $(date -u +%FT%TZ) on $TAG" | aws s3 cp --quiet - $U/state/${NAME}_fail; mirror
elif grep -q "FINAL_DEV_BELOW_BAR" $Q/logs/arm_$NAME.log; then
  python3 $UW/code/uog1_result.py $NAME $MANIFEST > $UW/logs/uog1_result.log 2>&1; aws s3 sync --quiet $Q/runs/$NAME $A/runs/$NAME/ --exclude "ckpt_*"
  mirror; echo below_bar | aws s3 cp --quiet - $U/state/${NAME}_chain_done; log "CHAIN_DONE (arm below its dev bar: no public read)"
elif grep -q '"why": "gate_stop"' $Q/runs/$NAME/train_log.jsonl 2>/dev/null; then
  mirror; echo dev_collapse | aws s3 cp --quiet - $U/state/${NAME}_chain_done; log "CHAIN_DONE (dev collapse stop: no public read)"
else log "ARM_NOT_FINISHED (a re-run of this chain resumes it) :: $(grep -E "Error|Traceback" $Q/logs/train_$NAME.out 2>/dev/null | tail -1 | cut -c1-200)"
  [ "$(tail -n 40 $L | grep -c ARM_NOT_FINISHED)" -ge 3 ] && { echo "three unfinished arm runs in a row $(date -u +%FT%TZ) on $TAG" | aws s3 cp --quiet - $U/state/${NAME}_fail; log "HELD after 3 unfinished runs in a row: ${NAME}_fail written"; }
fi
kill $MIR 2>/dev/null; mirror
